-- Data only. Existing level IDs, submissions, and player achievements are preserved.
BEGIN;
SELECT pg_advisory_xact_lock(742918);
UPDATE public.levels AS l
SET chapter = x.chapter, level_name = x.level_name, description = x.description,
    objective = x.objective, starter_code = x.starter_code,
    difficulty = x.difficulty, map_data = x.map_data
FROM jsonb_to_recordset('[{"chapter":1,"level_name":"The Awakening Altar","description":"Master grid movement and learn the first incantation: print().","objective":"Command the wizard to walk to the <span class=''highlight''>Awakening Altar</span> at (6, 2) and chant <span class=''highlight''>print(''Lumina'')</span>!","starter_code":"# Move your hero to the Awakening Altar at (6, 2)\n# and speak the sacred name: \"Lumina\" using print()\n\nhero.move_right(5)\nprint(\"Lumina\")\n","difficulty":"Easy","map_data":{"catalog":"spectrum_stages_v1","stage_key":"1-1","stage_type":"lesson","xp_reward":150,"arena":{"cols":8,"rows":5,"theme":"forest","spawn":{"x":1,"y":2},"altar":{"x":6,"y":2,"name":"Awakening Altar","keyword":"Lumina"},"obstacles":[{"x":3,"y":0},{"x":4,"y":0},{"x":3,"y":4},{"x":4,"y":4}]}}},{"chapter":1,"level_name":"The Alchemist''s Flasks","description":"Sort variables into Flasks (str, int, float, bool) with real type validation.","objective":"Sort all 4 value crystals into their matching Data Type flasks: <span class=''highlight''>''str''</span>, <span class=''highlight''>''int''</span>, <span class=''highlight''>''float''</span>, and <span class=''highlight''>''bool''</span>!","starter_code":"# The Alchemist''s Flasks — Variable Types Sorting\n# Available commands:\n#   hero.move_right(n), hero.move_left(n), hero.move_up(n), hero.move_down(n)\n#   hero.pick_up()\n#   hero.put_in(\"str\" | \"int\" | \"float\" | \"bool\")\n\n# Step 1: Pick up \"Lumina\" (String) and place in [str] flask\nhero.move_right(1)\nhero.move_down(2)\nhero.pick_up()\nhero.move_up(2)\nhero.put_in(\"str\")\n\n# Step 2: Pick up 255 (Integer at 4, 5) and put in \"int\" flask at (4, 1)\n\n\n# Step 3: Pick up 3.14 (Float at 6, 4) and put in \"float\" flask at (6, 1)\n\n\n# Step 4: Pick up True (Boolean at 8, 5) and put in \"bool\" flask at (8, 1)\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"1-2","stage_type":"lesson","xp_reward":300,"arena":{"cols":10,"rows":7,"theme":"lab","spawn":{"x":1,"y":2},"flasks":[{"id":"str","type":"str","label":"[str] String","name":"Flask of Strings","x":2,"y":1,"color":"#ec4899","icon":"fas fa-quote-right"},{"id":"int","type":"int","label":"[int] Integer","name":"Flask of Integers","x":4,"y":1,"color":"#06b6d4","icon":"fas fa-hashtag"},{"id":"float","type":"float","label":"[float] Float","name":"Flask of Floats","x":6,"y":1,"color":"#10b981","icon":"fas fa-percentage"},{"id":"bool","type":"bool","label":"[bool] Boolean","name":"Flask of Booleans","x":8,"y":1,"color":"#f59e0b","icon":"fas fa-toggle-on"}],"items":[{"id":"val-1","value":"Lumina","display":"\"Lumina\"","type":"str","x":2,"y":4,"icon":"fas fa-gem","color":"#ec4899"},{"id":"val-2","value":255,"display":"255","type":"int","x":4,"y":5,"icon":"fas fa-dice-d20","color":"#06b6d4"},{"id":"val-3","value":3.14,"display":"3.14","type":"float","x":6,"y":4,"icon":"fas fa-atom","color":"#10b981"},{"id":"val-4","value":true,"display":"True","type":"bool","x":8,"y":5,"icon":"fas fa-bolt","color":"#f59e0b"}],"obstacles":[{"x":0,"y":0},{"x":1,"y":0},{"x":2,"y":0},{"x":3,"y":0},{"x":4,"y":0},{"x":5,"y":0},{"x":6,"y":0},{"x":7,"y":0},{"x":8,"y":0},{"x":9,"y":0}]}}},{"chapter":1,"level_name":"The Prism Crystals","description":"Navigate the crystal cavern and cast RGB colored light into ancient braziers.","objective":"Walk to all three braziers and cast their matching pure colors: <span class=''highlight''>Red (255, 0, 0)</span>, <span class=''highlight''>Green (0, 255, 0)</span>, and <span class=''highlight''>Blue (0, 0, 255)</span>!","starter_code":"# Ignite the three elemental braziers with pure RGB light!\n# hero.cast_color(red, green, blue)\n\n# Step 1: Walk to Red Brazier at (3, 2) and cast Red\nhero.move_right(2)\nhero.cast_color(255, 0, 0)\n\n# Step 2: Walk to Green Brazier at (6, 2) and cast Green\n\n\n# Step 3: Walk to Blue Brazier at (8, 2) and cast Blue\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"1-3","stage_type":"challenge","xp_reward":350,"arena":{"cols":10,"rows":6,"theme":"crystals","spawn":{"x":1,"y":2},"braziers":[{"id":"br-red","name":"Red Brazier","targetColorName":"Red (255, 0, 0)","x":3,"y":2},{"id":"br-green","name":"Green Brazier","targetColorName":"Green (0, 255, 0)","x":6,"y":2},{"id":"br-blue","name":"Blue Brazier","targetColorName":"Blue (0, 0, 255)","x":8,"y":2}],"obstacles":[{"x":3,"y":0},{"x":6,"y":0},{"x":8,"y":0},{"x":3,"y":5},{"x":6,"y":5},{"x":8,"y":5}]}}},{"chapter":1,"level_name":"The Prism Gate","description":"The grand trial: navigate obstacles, cast RGB light, and chant the opening phrase.","objective":"1. Pick up the Key at (2, 1) and put it into the Lock Flask at (2, 5)<br/>2. Navigate to the Brazier at (5, 3) and cast <span class=''highlight''>hero.cast_color(255, 0, 0)</span><br/>3. Walk to the Gate at (10, 3) and chant: <span class=''highlight''>print(f''Open, {spell}!'')</span>","starter_code":"# The Prism Gate — Boss Trial\n# Combine: Movement + Variables + Flasks + RGB Light + f-strings!\n\nspell = \"The Prism Gate\"\n\n# Step 1: Collect the Key at (2, 1) and deposit it into the ''str'' Lock Flask at (2, 5)\nhero.move_right(2)\nhero.move_up(2)\nhero.pick_up()\nhero.move_down(4)\nhero.put_in(\"str\")\n\n# Step 2: Navigate around the stone wall to the Brazier at (5, 3) and cast Red light\nhero.move_up(2)\nhero.move_right(3)\nhero.cast_color(255, 0, 0)\n\n# Step 3: Move to the Gate at (10, 3) and chant using f-string\nhero.move_right(5)\nprint(f\"Open, {spell}!\")\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"1-4","stage_type":"boss","xp_reward":500,"arena":{"cols":11,"rows":6,"theme":"gate","spawn":{"x":0,"y":3},"gate":{"x":10,"y":3,"name":"The Prism Gate","locked":true},"braziers":[{"id":"gate-brazier","name":"Gate Guardian Brazier","targetColorName":"Red (255, 0, 0)","x":5,"y":3}],"items":[{"id":"gate-key","value":"SPECTRUM_KEY","display":"\"SPECTRUM_KEY\"","type":"str","x":2,"y":1,"icon":"fas fa-key","color":"#f59e0b"}],"flasks":[{"id":"str","type":"str","label":"[str] Lock Flask","name":"Flask of Key","x":2,"y":5,"color":"#f59e0b","icon":"fas fa-lock-open"}],"obstacles":[{"x":4,"y":1},{"x":4,"y":2},{"x":4,"y":4},{"x":4,"y":5},{"x":8,"y":0},{"x":8,"y":1},{"x":8,"y":4},{"x":8,"y":5}]}}},{"chapter":1,"level_name":"The Sleeping Garden","description":"Mix red and green light to restore a golden flower.","objective":"Walk beside the Golden Flower at (5, 2) and restore its yellow light with hero.cast_color(255, 255, 0).","starter_code":"# The flower needs yellow light (red + green).\n# Walk beside the flower at (5, 2), then cast its color.\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"1-5","stage_type":"challenge","xp_reward":375,"arena":{"cols":8,"rows":5,"theme":"forest","spawn":{"x":1,"y":2},"colorTargets":[{"id":"golden-flower","name":"Golden Flower","icon":"fas fa-seedling","x":5,"y":2,"targetRgb":[255,255,0]}]}}},{"chapter":1,"level_name":"The Swapped Canvas","description":"Fix swapped RGB channels to color two enchanted frames.","objective":"Fix the two color spells. The frame at (3, 2) needs red (255, 0, 0); the frame at (7, 2) needs blue (0, 0, 255).","starter_code":"# The painter swapped red and blue. Fix both calls!\nhero.move_right(2)\nhero.cast_color(0, 0, 255)  # Red Frame\nhero.move_right(4)\nhero.cast_color(255, 0, 0)  # Blue Frame\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"1-6","stage_type":"challenge","xp_reward":400,"arena":{"cols":9,"rows":5,"theme":"forest","spawn":{"x":1,"y":2},"colorTargets":[{"id":"red-frame","name":"Red Frame","icon":"fas fa-image","x":3,"y":2,"targetRgb":[255,0,0]},{"id":"blue-frame","name":"Blue Frame","icon":"fas fa-image","x":7,"y":2,"targetRgb":[0,0,255]}]}}},{"chapter":1,"level_name":"The Three Seasons","description":"Use variables and movement to color three seasonal relics.","objective":"Color the relics at (2, 2), (5, 2), and (8, 2): yellow (255, 255, 0), cyan (0, 255, 255), and magenta (255, 0, 255).","starter_code":"# Use variables to keep track of each RGB channel.\nred = 255\ngreen = 255\nblue = 0\n\nhero.move_right(1)\nhero.cast_color(red, green, blue)  # Summer: yellow\n\n# Move to Spring and cast cyan, then Autumn and cast magenta.\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"1-7","stage_type":"challenge","xp_reward":450,"arena":{"cols":10,"rows":5,"theme":"forest","spawn":{"x":1,"y":2},"colorTargets":[{"id":"summer","name":"Summer Relic","icon":"fas fa-sun","x":2,"y":2,"targetRgb":[255,255,0]},{"id":"spring","name":"Spring Relic","icon":"fas fa-leaf","x":5,"y":2,"targetRgb":[0,255,255]},{"id":"autumn","name":"Autumn Relic","icon":"fas fa-gem","x":8,"y":2,"targetRgb":[255,0,255]}]}}},{"chapter":2,"level_name":"The Faded Manuscript","description":"Brighten a faded manuscript with RGB arithmetic.","objective":"Brighten the manuscript ink from <span class=\"highlight\">(80, 55, 30)</span> by 40 per channel. Move beside it and cast the calculated RGB color.","starter_code":"# Brighten each channel by 40, then move beside the manuscript.\nr, g, b = 80, 55, 30\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"2-1","stage_type":"lesson","xp_reward":200,"arena":{"theme":"archive","blockMovement":true,"cols":8,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"manuscript","name":"Faded Manuscript"}],"colorTargets":[{"id":"manuscript-ink","muralId":"manuscript","name":"Golden Ink","icon":"fas fa-scroll","x":5,"y":2,"sourceRgb":[80,55,30],"targetRgb":[120,95,70]}],"obstacles":[{"x":3,"y":0},{"x":4,"y":0}]}}},{"chapter":2,"level_name":"The Tinted Lenses","description":"Tint two lenses by changing one color channel at a time.","objective":"Warm the first lens by adding <span class=\"highlight\">50 red</span>. Cool the second by adding <span class=\"highlight\">80 blue</span>. Restore both with code.","starter_code":"# Warm the first lens and cool the second.\nwarm_r, warm_g, warm_b = 45, 90, 170\ncool_r, cool_g, cool_b = 160, 90, 40\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"2-2","stage_type":"challenge","xp_reward":200,"arena":{"theme":"archive","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"colorTargets":[{"id":"warm-lens","name":"Warm Lens","icon":"fas fa-sun","x":3,"y":2,"sourceRgb":[45,90,170],"targetRgb":[95,90,170]},{"id":"cool-lens","name":"Cool Lens","icon":"fas fa-eye","x":7,"y":2,"sourceRgb":[160,90,40],"targetRgb":[160,90,120]}],"obstacles":[{"x":5,"y":0},{"x":5,"y":4}]}}},{"chapter":2,"level_name":"The Mirror Gallery","description":"Invert the colors of two enchanted reflections.","objective":"Invert both mirror images. For each RGB channel, calculate <span class=\"highlight\">255 - channel</span>, then cast the result beside its mirror.","starter_code":"# Invert each mirror by subtracting its channels from 255.\nfirst_r, first_g, first_b = 40, 90, 150\nsecond_r, second_g, second_b = 200, 80, 20\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"2-3","stage_type":"challenge","xp_reward":250,"arena":{"theme":"archive","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"mirrors","name":"Mirror Gallery"}],"colorTargets":[{"id":"mirror-a","muralId":"mirrors","name":"First Reflection","icon":"fas fa-image","x":3,"y":2,"sourceRgb":[40,90,150],"targetRgb":[215,165,105]},{"id":"mirror-b","muralId":"mirrors","name":"Second Reflection","icon":"fas fa-image","x":7,"y":2,"sourceRgb":[200,80,20],"targetRgb":[55,175,235]}]}}},{"chapter":2,"level_name":"Gray Memory","description":"Restore a three-panel image in grayscale.","objective":"Restore the three memory panels in grayscale. Compute <span class=\"highlight\">(r + g + b) // 3</span> for each panel and cast that value into all channels.","starter_code":"# Calculate a grayscale shade for each panel.\nfirst_r, first_g, first_b = 30, 90, 150\nmiddle_r, middle_g, middle_b = 180, 60, 30\nfinal_r, final_g, final_b = 15, 135, 210\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"2-4","stage_type":"challenge","xp_reward":300,"arena":{"theme":"archive","blockMovement":true,"cols":10,"rows":6,"spawn":{"x":1,"y":3},"murals":[{"id":"memory","name":"Memory Triptych"}],"colorTargets":[{"id":"memory-a","muralId":"memory","name":"First Panel","icon":"fas fa-image","x":2,"y":1,"sourceRgb":[30,90,150],"targetRgb":[90,90,90]},{"id":"memory-b","muralId":"memory","name":"Middle Panel","icon":"fas fa-image","x":5,"y":1,"sourceRgb":[180,60,30],"targetRgb":[90,90,90]},{"id":"memory-c","muralId":"memory","name":"Final Panel","icon":"fas fa-image","x":8,"y":1,"sourceRgb":[15,135,210],"targetRgb":[120,120,120]}]}}},{"chapter":2,"level_name":"The Palette Lock","description":"Combine color transformations to open the prism vault.","objective":"Open three locks using the right transformation: <span class=\"highlight\">+40 brightness</span>, <span class=\"highlight\">inversion</span>, then <span class=\"highlight\">grayscale</span>.","starter_code":"# Restore the three locks in order.\nbright_r, bright_g, bright_b = 110, 60, 30\ninverse_r, inverse_g, inverse_b = 20, 100, 160\ngray_r, gray_g, gray_b = 20, 80, 140\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"2-5","stage_type":"challenge","xp_reward":200,"arena":{"theme":"archive","blockMovement":true,"cols":10,"rows":6,"spawn":{"x":1,"y":3},"colorTargets":[{"id":"bright-lock","name":"Radiance Lock","icon":"fas fa-lock","x":2,"y":1,"sourceRgb":[110,60,30],"targetRgb":[150,100,70]},{"id":"inverse-lock","name":"Mirror Lock","icon":"fas fa-lock","x":5,"y":1,"sourceRgb":[20,100,160],"targetRgb":[235,155,95]},{"id":"gray-lock","name":"Silver Lock","icon":"fas fa-lock","x":8,"y":1,"sourceRgb":[20,80,140],"targetRgb":[80,80,80]}],"obstacles":[{"x":3,"y":3},{"x":6,"y":3}]}}},{"chapter":2,"level_name":"The Living Atlas","description":"Restore three Atlas pages and open the final gate.","objective":"Restore the Atlas pages with <span class=\"highlight\">+50 brightness</span>, <span class=\"highlight\">inversion</span>, and <span class=\"highlight\">grayscale</span>. Then move beside the Atlas Gate.","starter_code":"# Restore all three pages, then reach the gate at (9, 4).\nlight_r, light_g, light_b = 40, 60, 90\nmirror_r, mirror_g, mirror_b = 20, 100, 180\nsilver_r, silver_g, silver_b = 120, 60, 30\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"2-6","stage_type":"boss","xp_reward":500,"arena":{"theme":"archive","blockMovement":true,"cols":10,"rows":6,"spawn":{"x":1,"y":4},"murals":[{"id":"atlas","name":"Living Atlas"}],"colorTargets":[{"id":"atlas-light","muralId":"atlas","name":"Sunlit Page","icon":"fas fa-scroll","x":2,"y":1,"sourceRgb":[40,60,90],"targetRgb":[90,110,140]},{"id":"atlas-mirror","muralId":"atlas","name":"Mirror Page","icon":"fas fa-scroll","x":5,"y":1,"sourceRgb":[20,100,180],"targetRgb":[235,155,75]},{"id":"atlas-gray","muralId":"atlas","name":"Silver Page","icon":"fas fa-scroll","x":8,"y":1,"sourceRgb":[120,60,30],"targetRgb":[70,70,70]}],"gate":{"x":9,"y":4,"name":"Atlas Gate"},"obstacles":[{"x":4,"y":4},{"x":7,"y":4}]}}},{"chapter":3,"level_name":"The Inscription Wall","description":"Learn about lists and how to create them.","objective":"Return a new list containing the three pixels in their original order. <span class=\"highlight\">A digital image is a list of RGB pixels; each rune is one pixel.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[220,40,35],[40,200,90],[35,90,220]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-1","stage_type":"lesson","xp_reward":220,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-1-image","name":"The Inscription Wall image"}],"colorTargets":[{"id":"3-1-pixel-0","name":"Pixel 1","icon":"fas fa-th-list","x":2,"y":2,"sourceRgb":[220,40,35],"targetRgb":[220,40,35],"muralId":"3-1-image"},{"id":"3-1-pixel-1","name":"Pixel 2","icon":"fas fa-th-list","x":5,"y":2,"sourceRgb":[40,200,90],"targetRgb":[40,200,90],"muralId":"3-1-image"},{"id":"3-1-pixel-2","name":"Pixel 3","icon":"fas fa-th-list","x":8,"y":2,"sourceRgb":[35,90,220],"targetRgb":[35,90,220],"muralId":"3-1-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":3,"level_name":"Rune Positions","description":"Use pixel positions to repair a scrambled image.","objective":"The first and last pixels were swapped. Return them in the correct order. <span class=\"highlight\">Pixel indexing locates an exact position in an image row.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[35,90,220],[40,200,90],[220,40,35]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-2","stage_type":"challenge","xp_reward":240,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-2-image","name":"Rune Positions image"}],"colorTargets":[{"id":"3-2-pixel-0","name":"Pixel 1","icon":"fas fa-hand-pointer","x":2,"y":2,"sourceRgb":[35,90,220],"targetRgb":[220,40,35],"muralId":"3-2-image"},{"id":"3-2-pixel-1","name":"Pixel 2","icon":"fas fa-hand-pointer","x":5,"y":2,"sourceRgb":[40,200,90],"targetRgb":[40,200,90],"muralId":"3-2-image"},{"id":"3-2-pixel-2","name":"Pixel 3","icon":"fas fa-hand-pointer","x":8,"y":2,"sourceRgb":[220,40,35],"targetRgb":[35,90,220],"muralId":"3-2-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":3,"level_name":"The Matrix Search","description":"Find values in lists using .index().","objective":"Find the pixel with the most red using .index() and max(). Turn that pixel gold. <span class=\"highlight\">Searching a pixel row finds the brightest red sample, a simple feature detector.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[20,50,90],[180,30,50],[70,70,70]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-3","stage_type":"challenge","xp_reward":280,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-3-image","name":"The Matrix Search image"}],"colorTargets":[{"id":"3-3-pixel-0","name":"Pixel 1","icon":"fas fa-search","x":2,"y":2,"sourceRgb":[20,50,90],"targetRgb":[20,50,90],"muralId":"3-3-image"},{"id":"3-3-pixel-1","name":"Pixel 2","icon":"fas fa-search","x":5,"y":2,"sourceRgb":[180,30,50],"targetRgb":[255,200,40],"muralId":"3-3-image"},{"id":"3-3-pixel-2","name":"Pixel 3","icon":"fas fa-search","x":8,"y":2,"sourceRgb":[70,70,70],"targetRgb":[70,70,70],"muralId":"3-3-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":3,"level_name":"The Echo Loop","description":"Learn for loops to iterate over lists.","objective":"Brighten every channel by 30, stopping at 255. <span class=\"highlight\">A for loop applies the same image filter to every pixel.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[50,70,90],[140,40,70],[240,220,200]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-4","stage_type":"lesson","xp_reward":290,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-4-image","name":"The Echo Loop image"}],"colorTargets":[{"id":"3-4-pixel-0","name":"Pixel 1","icon":"fas fa-sync-alt","x":2,"y":2,"sourceRgb":[50,70,90],"targetRgb":[80,100,120],"muralId":"3-4-image"},{"id":"3-4-pixel-1","name":"Pixel 2","icon":"fas fa-sync-alt","x":5,"y":2,"sourceRgb":[140,40,70],"targetRgb":[170,70,100],"muralId":"3-4-image"},{"id":"3-4-pixel-2","name":"Pixel 3","icon":"fas fa-sync-alt","x":8,"y":2,"sourceRgb":[240,220,200],"targetRgb":[255,250,230],"muralId":"3-4-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":3,"level_name":"Broken Arrays","description":"Repair a broken pixel processing loop.","objective":"Fix the loop so it adds 20 to red only, capped at 255; keep green and blue. <span class=\"highlight\">A faulty loop shifts pixel channels and corrupts an image.</span>","starter_code":"def transform(pixels):\n    result = []\n    for pixel in pixels:\n        result.append([min(255, pixel[1] + 20), pixel[0], pixel[2]])\n    return result\n\npixels = [[20,40,90],[80,140,30],[250,20,50]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-5","stage_type":"challenge","xp_reward":310,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-5-image","name":"Broken Arrays image"}],"colorTargets":[{"id":"3-5-pixel-0","name":"Pixel 1","icon":"fas fa-bug","x":2,"y":2,"sourceRgb":[20,40,90],"targetRgb":[40,40,90],"muralId":"3-5-image"},{"id":"3-5-pixel-1","name":"Pixel 2","icon":"fas fa-bug","x":5,"y":2,"sourceRgb":[80,140,30],"targetRgb":[100,140,30],"muralId":"3-5-image"},{"id":"3-5-pixel-2","name":"Pixel 3","icon":"fas fa-bug","x":8,"y":2,"sourceRgb":[250,20,50],"targetRgb":[255,20,50],"muralId":"3-5-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":3,"level_name":"Pixel Trail","description":"Walk through a row of pixels and restore each color.","objective":"Reverse the row with a loop and append(), so the rune trail reads from right to left. <span class=\"highlight\">Traversing a pixel row restores an image one sample at a time.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[35,90,220],[40,200,90],[220,40,35]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-7","stage_type":"challenge","xp_reward":330,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-7-image","name":"Pixel Trail image"}],"colorTargets":[{"id":"3-7-pixel-0","name":"Pixel 1","icon":"fas fa-route","x":2,"y":2,"sourceRgb":[35,90,220],"targetRgb":[220,40,35],"muralId":"3-7-image"},{"id":"3-7-pixel-1","name":"Pixel 2","icon":"fas fa-route","x":5,"y":2,"sourceRgb":[40,200,90],"targetRgb":[40,200,90],"muralId":"3-7-image"},{"id":"3-7-pixel-2","name":"Pixel 3","icon":"fas fa-route","x":8,"y":2,"sourceRgb":[220,40,35],"targetRgb":[35,90,220],"muralId":"3-7-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":3,"level_name":"The Hidden Pattern","description":"Find a repeated color pattern in the rune image.","objective":"If the outer pixels match, make the center gold; otherwise leave the row unchanged. <span class=\"highlight\">A repeated pixel pattern can reveal a feature hidden in an image.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[220,40,35],[30,30,30],[220,40,35]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-8","stage_type":"challenge","xp_reward":350,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-8-image","name":"The Hidden Pattern image"}],"colorTargets":[{"id":"3-8-pixel-0","name":"Pixel 1","icon":"fas fa-chess-board","x":2,"y":2,"sourceRgb":[220,40,35],"targetRgb":[220,40,35],"muralId":"3-8-image"},{"id":"3-8-pixel-1","name":"Pixel 2","icon":"fas fa-chess-board","x":5,"y":2,"sourceRgb":[30,30,30],"targetRgb":[255,200,40],"muralId":"3-8-image"},{"id":"3-8-pixel-2","name":"Pixel 3","icon":"fas fa-chess-board","x":8,"y":2,"sourceRgb":[220,40,35],"targetRgb":[220,40,35],"muralId":"3-8-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":3,"level_name":"The Peak Trial","description":"Use lists, indexing, and loops to restore the summit image.","objective":"Brighten every pixel by 20, then mark the brightest original red pixel gold. <span class=\"highlight\">Indexing, searching, and loops combine to locate and restore image features.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[30,40,50],[200,30,20],[70,80,90]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)\nhero.move_down(2)","difficulty":"Hard","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-6","stage_type":"boss","xp_reward":450,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-6-image","name":"The Peak Trial image"}],"colorTargets":[{"id":"3-6-pixel-0","name":"Pixel 1","icon":"fas fa-crown","x":2,"y":2,"sourceRgb":[30,40,50],"targetRgb":[50,60,70],"muralId":"3-6-image"},{"id":"3-6-pixel-1","name":"Pixel 2","icon":"fas fa-crown","x":5,"y":2,"sourceRgb":[200,30,20],"targetRgb":[255,200,40],"muralId":"3-6-image"},{"id":"3-6-pixel-2","name":"Pixel 3","icon":"fas fa-crown","x":8,"y":2,"sourceRgb":[70,80,90],"targetRgb":[90,100,110],"muralId":"3-6-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}],"gate":{"x":9,"y":4,"name":"Summit Gate"}}}},{"chapter":4,"level_name":"The Crossroads","description":"Learn if/elif/else conditional logic.","objective":"For every pixel, average its RGB values. Use white when the average is at least 128, otherwise black. <span class=\"highlight\">Thresholding turns image brightness into a black or white mask.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[30,30,30],[180,180,180],[90,150,120]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-1","stage_type":"lesson","xp_reward":300,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-1-image","name":"The Crossroads image"}],"colorTargets":[{"id":"4-1-pixel-0","name":"Pixel 1","icon":"fas fa-code-branch","x":2,"y":2,"sourceRgb":[30,30,30],"targetRgb":[0,0,0],"muralId":"4-1-image"},{"id":"4-1-pixel-1","name":"Pixel 2","icon":"fas fa-code-branch","x":5,"y":2,"sourceRgb":[180,180,180],"targetRgb":[255,255,255],"muralId":"4-1-image"},{"id":"4-1-pixel-2","name":"Pixel 3","icon":"fas fa-code-branch","x":8,"y":2,"sourceRgb":[90,150,120],"targetRgb":[0,0,0],"muralId":"4-1-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":4,"level_name":"Path Selection","description":"Choose an image filter with if, elif, and else.","objective":"Classify average brightness: below 85 blue, below 170 gold, otherwise white. <span class=\"highlight\">if/elif/else selects a different filter for each brightness range.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[30,30,30],[120,120,120],[220,220,220]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-2","stage_type":"challenge","xp_reward":320,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-2-image","name":"Path Selection image"}],"colorTargets":[{"id":"4-2-pixel-0","name":"Pixel 1","icon":"fas fa-directions","x":2,"y":2,"sourceRgb":[30,30,30],"targetRgb":[35,90,220],"muralId":"4-2-image"},{"id":"4-2-pixel-1","name":"Pixel 2","icon":"fas fa-directions","x":5,"y":2,"sourceRgb":[120,120,120],"targetRgb":[255,200,40],"muralId":"4-2-image"},{"id":"4-2-pixel-2","name":"Pixel 3","icon":"fas fa-directions","x":8,"y":2,"sourceRgb":[220,220,220],"targetRgb":[240,240,240],"muralId":"4-2-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":4,"level_name":"Truth and Lies","description":"Combine boolean masks to reveal hidden pixels.","objective":"Keep a pixel only if red is above 100 AND blue is below 100; make all others black. <span class=\"highlight\">Boolean masks select pixels by combining channel conditions.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[180,30,40],[40,200,40],[180,30,180]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-3","stage_type":"challenge","xp_reward":340,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-3-image","name":"Truth and Lies image"}],"colorTargets":[{"id":"4-3-pixel-0","name":"Pixel 1","icon":"fas fa-toggle-on","x":2,"y":2,"sourceRgb":[180,30,40],"targetRgb":[180,30,40],"muralId":"4-3-image"},{"id":"4-3-pixel-1","name":"Pixel 2","icon":"fas fa-toggle-on","x":5,"y":2,"sourceRgb":[40,200,40],"targetRgb":[0,0,0],"muralId":"4-3-image"},{"id":"4-3-pixel-2","name":"Pixel 3","icon":"fas fa-toggle-on","x":8,"y":2,"sourceRgb":[180,30,180],"targetRgb":[0,0,0],"muralId":"4-3-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":4,"level_name":"Broken Bridges","description":"Repair conditional logic in a broken image mask.","objective":"Fix the comparison: keep pixels whose average brightness is at least 100; black out the rest. <span class=\"highlight\">A reversed comparison breaks a threshold mask and hides the wrong pixels.</span>","starter_code":"def transform(pixels):\n    result = []\n    for pixel in pixels:\n        if sum(pixel) / 3 < 100:\n            result.append(pixel)\n        else:\n            result.append([0, 0, 0])\n    return result\n\npixels = [[30,30,30],[100,100,100],[200,150,100]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-4","stage_type":"challenge","xp_reward":360,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-4-image","name":"Broken Bridges image"}],"colorTargets":[{"id":"4-4-pixel-0","name":"Pixel 1","icon":"fas fa-bug","x":2,"y":2,"sourceRgb":[30,30,30],"targetRgb":[0,0,0],"muralId":"4-4-image"},{"id":"4-4-pixel-1","name":"Pixel 2","icon":"fas fa-bug","x":5,"y":2,"sourceRgb":[100,100,100],"targetRgb":[100,100,100],"muralId":"4-4-image"},{"id":"4-4-pixel-2","name":"Pixel 3","icon":"fas fa-bug","x":8,"y":2,"sourceRgb":[200,150,100],"targetRgb":[200,150,100],"muralId":"4-4-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":4,"level_name":"The Color Mixer","description":"Use conditionals to mix colors dynamically.","objective":"If red is strongest, add 40 green; otherwise add 40 blue. Cap the changed channel at 255. <span class=\"highlight\">Conditional color mixing changes RGB channels based on the source pixel.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[190,30,20],[20,180,40],[10,20,210]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-5","stage_type":"challenge","xp_reward":380,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-5-image","name":"The Color Mixer image"}],"colorTargets":[{"id":"4-5-pixel-0","name":"Pixel 1","icon":"fas fa-tint","x":2,"y":2,"sourceRgb":[190,30,20],"targetRgb":[190,70,20],"muralId":"4-5-image"},{"id":"4-5-pixel-1","name":"Pixel 2","icon":"fas fa-tint","x":5,"y":2,"sourceRgb":[20,180,40],"targetRgb":[20,180,80],"muralId":"4-5-image"},{"id":"4-5-pixel-2","name":"Pixel 3","icon":"fas fa-tint","x":8,"y":2,"sourceRgb":[10,20,210],"targetRgb":[10,20,250],"muralId":"4-5-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":4,"level_name":"Shadow Boundaries","description":"Detect light and shadow boundaries between pixels.","objective":"Make a pixel gold if its average brightness differs from the previous pixel by at least 80; keep other pixels. <span class=\"highlight\">Edge detection compares neighboring pixels to find a light to shadow boundary.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[30,30,30],[200,200,200],[210,210,210]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-7","stage_type":"challenge","xp_reward":400,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-7-image","name":"Shadow Boundaries image"}],"colorTargets":[{"id":"4-7-pixel-0","name":"Pixel 1","icon":"fas fa-adjust","x":2,"y":2,"sourceRgb":[30,30,30],"targetRgb":[30,30,30],"muralId":"4-7-image"},{"id":"4-7-pixel-1","name":"Pixel 2","icon":"fas fa-adjust","x":5,"y":2,"sourceRgb":[200,200,200],"targetRgb":[255,200,40],"muralId":"4-7-image"},{"id":"4-7-pixel-2","name":"Pixel 3","icon":"fas fa-adjust","x":8,"y":2,"sourceRgb":[210,210,210],"targetRgb":[210,210,210],"muralId":"4-7-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":4,"level_name":"The Color Seal","description":"Combine masks and color mixing to open the seal.","objective":"Turn pixels with every channel below 100 into gold. For all others, brighten blue by 20. <span class=\"highlight\">A color mask identifies dark pixels before applying an RGB transformation.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[20,30,40],[180,60,40],[40,150,240]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-8","stage_type":"challenge","xp_reward":420,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-8-image","name":"The Color Seal image"}],"colorTargets":[{"id":"4-8-pixel-0","name":"Pixel 1","icon":"fas fa-shield-alt","x":2,"y":2,"sourceRgb":[20,30,40],"targetRgb":[255,200,40],"muralId":"4-8-image"},{"id":"4-8-pixel-1","name":"Pixel 2","icon":"fas fa-shield-alt","x":5,"y":2,"sourceRgb":[180,60,40],"targetRgb":[180,60,60],"muralId":"4-8-image"},{"id":"4-8-pixel-2","name":"Pixel 3","icon":"fas fa-shield-alt","x":8,"y":2,"sourceRgb":[40,150,240],"targetRgb":[40,150,255],"muralId":"4-8-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":4,"level_name":"The Light Convergence","description":"Restore the final image with a conditional RGB filter.","objective":"If average brightness is below 85, make white. If red is strongest, add 50 blue. Otherwise keep the pixel. Avoid the marked shadow tiles, restore all three seals, and reach the gate. <span class=\"highlight\">Two minutes of active execution time.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[20,30,40],[200,40,30],[40,180,90]]\ncolors = transform(pixels)\nfor index, color in enumerate(colors):\n    hero.cast_color(color[0], color[1], color[2])\n    if index < 2:\n        hero.move_up(1)\n        hero.move_right(3)\n        hero.move_down(1)\nhero.move_right(2)\nhero.move_down(2)","difficulty":"Hard","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-6","stage_type":"boss","xp_reward":600,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-6-image","name":"The Light Convergence image"}],"colorTargets":[{"id":"4-6-pixel-0","name":"Color Seal 1","icon":"fas fa-sun","x":2,"y":2,"sourceRgb":[20,30,40],"targetRgb":[255,255,255],"muralId":"4-6-image"},{"id":"4-6-pixel-1","name":"Color Seal 2","icon":"fas fa-sun","x":5,"y":2,"sourceRgb":[200,40,30],"targetRgb":[200,40,80],"muralId":"4-6-image"},{"id":"4-6-pixel-2","name":"Color Seal 3","icon":"fas fa-sun","x":8,"y":2,"sourceRgb":[40,180,90],"targetRgb":[40,180,90],"muralId":"4-6-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}],"gate":{"x":9,"y":4,"name":"Spectrum Gate"},"boss":{"name":"Krakk, Summus Magus Monotoniae","x":9,"y":0},"hazards":[{"x":3,"y":2},{"x":6,"y":2}]}}}]'::jsonb) AS x(chapter int, level_name text, description text, objective text, starter_code text, difficulty text, map_data jsonb)
WHERE l.map_data->>'catalog' = x.map_data->>'catalog'
  AND l.map_data->>'stage_key' = x.map_data->>'stage_key';
INSERT INTO public.levels (chapter, level_name, description, objective, starter_code, difficulty, map_data)
SELECT x.chapter, x.level_name, x.description, x.objective, x.starter_code, x.difficulty, x.map_data
FROM jsonb_to_recordset('[{"chapter":1,"level_name":"The Awakening Altar","description":"Master grid movement and learn the first incantation: print().","objective":"Command the wizard to walk to the <span class=''highlight''>Awakening Altar</span> at (6, 2) and chant <span class=''highlight''>print(''Lumina'')</span>!","starter_code":"# Move your hero to the Awakening Altar at (6, 2)\n# and speak the sacred name: \"Lumina\" using print()\n\nhero.move_right(5)\nprint(\"Lumina\")\n","difficulty":"Easy","map_data":{"catalog":"spectrum_stages_v1","stage_key":"1-1","stage_type":"lesson","xp_reward":150,"arena":{"cols":8,"rows":5,"theme":"forest","spawn":{"x":1,"y":2},"altar":{"x":6,"y":2,"name":"Awakening Altar","keyword":"Lumina"},"obstacles":[{"x":3,"y":0},{"x":4,"y":0},{"x":3,"y":4},{"x":4,"y":4}]}}},{"chapter":1,"level_name":"The Alchemist''s Flasks","description":"Sort variables into Flasks (str, int, float, bool) with real type validation.","objective":"Sort all 4 value crystals into their matching Data Type flasks: <span class=''highlight''>''str''</span>, <span class=''highlight''>''int''</span>, <span class=''highlight''>''float''</span>, and <span class=''highlight''>''bool''</span>!","starter_code":"# The Alchemist''s Flasks — Variable Types Sorting\n# Available commands:\n#   hero.move_right(n), hero.move_left(n), hero.move_up(n), hero.move_down(n)\n#   hero.pick_up()\n#   hero.put_in(\"str\" | \"int\" | \"float\" | \"bool\")\n\n# Step 1: Pick up \"Lumina\" (String) and place in [str] flask\nhero.move_right(1)\nhero.move_down(2)\nhero.pick_up()\nhero.move_up(2)\nhero.put_in(\"str\")\n\n# Step 2: Pick up 255 (Integer at 4, 5) and put in \"int\" flask at (4, 1)\n\n\n# Step 3: Pick up 3.14 (Float at 6, 4) and put in \"float\" flask at (6, 1)\n\n\n# Step 4: Pick up True (Boolean at 8, 5) and put in \"bool\" flask at (8, 1)\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"1-2","stage_type":"lesson","xp_reward":300,"arena":{"cols":10,"rows":7,"theme":"lab","spawn":{"x":1,"y":2},"flasks":[{"id":"str","type":"str","label":"[str] String","name":"Flask of Strings","x":2,"y":1,"color":"#ec4899","icon":"fas fa-quote-right"},{"id":"int","type":"int","label":"[int] Integer","name":"Flask of Integers","x":4,"y":1,"color":"#06b6d4","icon":"fas fa-hashtag"},{"id":"float","type":"float","label":"[float] Float","name":"Flask of Floats","x":6,"y":1,"color":"#10b981","icon":"fas fa-percentage"},{"id":"bool","type":"bool","label":"[bool] Boolean","name":"Flask of Booleans","x":8,"y":1,"color":"#f59e0b","icon":"fas fa-toggle-on"}],"items":[{"id":"val-1","value":"Lumina","display":"\"Lumina\"","type":"str","x":2,"y":4,"icon":"fas fa-gem","color":"#ec4899"},{"id":"val-2","value":255,"display":"255","type":"int","x":4,"y":5,"icon":"fas fa-dice-d20","color":"#06b6d4"},{"id":"val-3","value":3.14,"display":"3.14","type":"float","x":6,"y":4,"icon":"fas fa-atom","color":"#10b981"},{"id":"val-4","value":true,"display":"True","type":"bool","x":8,"y":5,"icon":"fas fa-bolt","color":"#f59e0b"}],"obstacles":[{"x":0,"y":0},{"x":1,"y":0},{"x":2,"y":0},{"x":3,"y":0},{"x":4,"y":0},{"x":5,"y":0},{"x":6,"y":0},{"x":7,"y":0},{"x":8,"y":0},{"x":9,"y":0}]}}},{"chapter":1,"level_name":"The Prism Crystals","description":"Navigate the crystal cavern and cast RGB colored light into ancient braziers.","objective":"Walk to all three braziers and cast their matching pure colors: <span class=''highlight''>Red (255, 0, 0)</span>, <span class=''highlight''>Green (0, 255, 0)</span>, and <span class=''highlight''>Blue (0, 0, 255)</span>!","starter_code":"# Ignite the three elemental braziers with pure RGB light!\n# hero.cast_color(red, green, blue)\n\n# Step 1: Walk to Red Brazier at (3, 2) and cast Red\nhero.move_right(2)\nhero.cast_color(255, 0, 0)\n\n# Step 2: Walk to Green Brazier at (6, 2) and cast Green\n\n\n# Step 3: Walk to Blue Brazier at (8, 2) and cast Blue\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"1-3","stage_type":"challenge","xp_reward":350,"arena":{"cols":10,"rows":6,"theme":"crystals","spawn":{"x":1,"y":2},"braziers":[{"id":"br-red","name":"Red Brazier","targetColorName":"Red (255, 0, 0)","x":3,"y":2},{"id":"br-green","name":"Green Brazier","targetColorName":"Green (0, 255, 0)","x":6,"y":2},{"id":"br-blue","name":"Blue Brazier","targetColorName":"Blue (0, 0, 255)","x":8,"y":2}],"obstacles":[{"x":3,"y":0},{"x":6,"y":0},{"x":8,"y":0},{"x":3,"y":5},{"x":6,"y":5},{"x":8,"y":5}]}}},{"chapter":1,"level_name":"The Prism Gate","description":"The grand trial: navigate obstacles, cast RGB light, and chant the opening phrase.","objective":"1. Pick up the Key at (2, 1) and put it into the Lock Flask at (2, 5)<br/>2. Navigate to the Brazier at (5, 3) and cast <span class=''highlight''>hero.cast_color(255, 0, 0)</span><br/>3. Walk to the Gate at (10, 3) and chant: <span class=''highlight''>print(f''Open, {spell}!'')</span>","starter_code":"# The Prism Gate — Boss Trial\n# Combine: Movement + Variables + Flasks + RGB Light + f-strings!\n\nspell = \"The Prism Gate\"\n\n# Step 1: Collect the Key at (2, 1) and deposit it into the ''str'' Lock Flask at (2, 5)\nhero.move_right(2)\nhero.move_up(2)\nhero.pick_up()\nhero.move_down(4)\nhero.put_in(\"str\")\n\n# Step 2: Navigate around the stone wall to the Brazier at (5, 3) and cast Red light\nhero.move_up(2)\nhero.move_right(3)\nhero.cast_color(255, 0, 0)\n\n# Step 3: Move to the Gate at (10, 3) and chant using f-string\nhero.move_right(5)\nprint(f\"Open, {spell}!\")\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"1-4","stage_type":"boss","xp_reward":500,"arena":{"cols":11,"rows":6,"theme":"gate","spawn":{"x":0,"y":3},"gate":{"x":10,"y":3,"name":"The Prism Gate","locked":true},"braziers":[{"id":"gate-brazier","name":"Gate Guardian Brazier","targetColorName":"Red (255, 0, 0)","x":5,"y":3}],"items":[{"id":"gate-key","value":"SPECTRUM_KEY","display":"\"SPECTRUM_KEY\"","type":"str","x":2,"y":1,"icon":"fas fa-key","color":"#f59e0b"}],"flasks":[{"id":"str","type":"str","label":"[str] Lock Flask","name":"Flask of Key","x":2,"y":5,"color":"#f59e0b","icon":"fas fa-lock-open"}],"obstacles":[{"x":4,"y":1},{"x":4,"y":2},{"x":4,"y":4},{"x":4,"y":5},{"x":8,"y":0},{"x":8,"y":1},{"x":8,"y":4},{"x":8,"y":5}]}}},{"chapter":1,"level_name":"The Sleeping Garden","description":"Mix red and green light to restore a golden flower.","objective":"Walk beside the Golden Flower at (5, 2) and restore its yellow light with hero.cast_color(255, 255, 0).","starter_code":"# The flower needs yellow light (red + green).\n# Walk beside the flower at (5, 2), then cast its color.\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"1-5","stage_type":"challenge","xp_reward":375,"arena":{"cols":8,"rows":5,"theme":"forest","spawn":{"x":1,"y":2},"colorTargets":[{"id":"golden-flower","name":"Golden Flower","icon":"fas fa-seedling","x":5,"y":2,"targetRgb":[255,255,0]}]}}},{"chapter":1,"level_name":"The Swapped Canvas","description":"Fix swapped RGB channels to color two enchanted frames.","objective":"Fix the two color spells. The frame at (3, 2) needs red (255, 0, 0); the frame at (7, 2) needs blue (0, 0, 255).","starter_code":"# The painter swapped red and blue. Fix both calls!\nhero.move_right(2)\nhero.cast_color(0, 0, 255)  # Red Frame\nhero.move_right(4)\nhero.cast_color(255, 0, 0)  # Blue Frame\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"1-6","stage_type":"challenge","xp_reward":400,"arena":{"cols":9,"rows":5,"theme":"forest","spawn":{"x":1,"y":2},"colorTargets":[{"id":"red-frame","name":"Red Frame","icon":"fas fa-image","x":3,"y":2,"targetRgb":[255,0,0]},{"id":"blue-frame","name":"Blue Frame","icon":"fas fa-image","x":7,"y":2,"targetRgb":[0,0,255]}]}}},{"chapter":1,"level_name":"The Three Seasons","description":"Use variables and movement to color three seasonal relics.","objective":"Color the relics at (2, 2), (5, 2), and (8, 2): yellow (255, 255, 0), cyan (0, 255, 255), and magenta (255, 0, 255).","starter_code":"# Use variables to keep track of each RGB channel.\nred = 255\ngreen = 255\nblue = 0\n\nhero.move_right(1)\nhero.cast_color(red, green, blue)  # Summer: yellow\n\n# Move to Spring and cast cyan, then Autumn and cast magenta.\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"1-7","stage_type":"challenge","xp_reward":450,"arena":{"cols":10,"rows":5,"theme":"forest","spawn":{"x":1,"y":2},"colorTargets":[{"id":"summer","name":"Summer Relic","icon":"fas fa-sun","x":2,"y":2,"targetRgb":[255,255,0]},{"id":"spring","name":"Spring Relic","icon":"fas fa-leaf","x":5,"y":2,"targetRgb":[0,255,255]},{"id":"autumn","name":"Autumn Relic","icon":"fas fa-gem","x":8,"y":2,"targetRgb":[255,0,255]}]}}},{"chapter":2,"level_name":"The Faded Manuscript","description":"Brighten a faded manuscript with RGB arithmetic.","objective":"Brighten the manuscript ink from <span class=\"highlight\">(80, 55, 30)</span> by 40 per channel. Move beside it and cast the calculated RGB color.","starter_code":"# Brighten each channel by 40, then move beside the manuscript.\nr, g, b = 80, 55, 30\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"2-1","stage_type":"lesson","xp_reward":200,"arena":{"theme":"archive","blockMovement":true,"cols":8,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"manuscript","name":"Faded Manuscript"}],"colorTargets":[{"id":"manuscript-ink","muralId":"manuscript","name":"Golden Ink","icon":"fas fa-scroll","x":5,"y":2,"sourceRgb":[80,55,30],"targetRgb":[120,95,70]}],"obstacles":[{"x":3,"y":0},{"x":4,"y":0}]}}},{"chapter":2,"level_name":"The Tinted Lenses","description":"Tint two lenses by changing one color channel at a time.","objective":"Warm the first lens by adding <span class=\"highlight\">50 red</span>. Cool the second by adding <span class=\"highlight\">80 blue</span>. Restore both with code.","starter_code":"# Warm the first lens and cool the second.\nwarm_r, warm_g, warm_b = 45, 90, 170\ncool_r, cool_g, cool_b = 160, 90, 40\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"2-2","stage_type":"challenge","xp_reward":200,"arena":{"theme":"archive","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"colorTargets":[{"id":"warm-lens","name":"Warm Lens","icon":"fas fa-sun","x":3,"y":2,"sourceRgb":[45,90,170],"targetRgb":[95,90,170]},{"id":"cool-lens","name":"Cool Lens","icon":"fas fa-eye","x":7,"y":2,"sourceRgb":[160,90,40],"targetRgb":[160,90,120]}],"obstacles":[{"x":5,"y":0},{"x":5,"y":4}]}}},{"chapter":2,"level_name":"The Mirror Gallery","description":"Invert the colors of two enchanted reflections.","objective":"Invert both mirror images. For each RGB channel, calculate <span class=\"highlight\">255 - channel</span>, then cast the result beside its mirror.","starter_code":"# Invert each mirror by subtracting its channels from 255.\nfirst_r, first_g, first_b = 40, 90, 150\nsecond_r, second_g, second_b = 200, 80, 20\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"2-3","stage_type":"challenge","xp_reward":250,"arena":{"theme":"archive","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"mirrors","name":"Mirror Gallery"}],"colorTargets":[{"id":"mirror-a","muralId":"mirrors","name":"First Reflection","icon":"fas fa-image","x":3,"y":2,"sourceRgb":[40,90,150],"targetRgb":[215,165,105]},{"id":"mirror-b","muralId":"mirrors","name":"Second Reflection","icon":"fas fa-image","x":7,"y":2,"sourceRgb":[200,80,20],"targetRgb":[55,175,235]}]}}},{"chapter":2,"level_name":"Gray Memory","description":"Restore a three-panel image in grayscale.","objective":"Restore the three memory panels in grayscale. Compute <span class=\"highlight\">(r + g + b) // 3</span> for each panel and cast that value into all channels.","starter_code":"# Calculate a grayscale shade for each panel.\nfirst_r, first_g, first_b = 30, 90, 150\nmiddle_r, middle_g, middle_b = 180, 60, 30\nfinal_r, final_g, final_b = 15, 135, 210\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"2-4","stage_type":"challenge","xp_reward":300,"arena":{"theme":"archive","blockMovement":true,"cols":10,"rows":6,"spawn":{"x":1,"y":3},"murals":[{"id":"memory","name":"Memory Triptych"}],"colorTargets":[{"id":"memory-a","muralId":"memory","name":"First Panel","icon":"fas fa-image","x":2,"y":1,"sourceRgb":[30,90,150],"targetRgb":[90,90,90]},{"id":"memory-b","muralId":"memory","name":"Middle Panel","icon":"fas fa-image","x":5,"y":1,"sourceRgb":[180,60,30],"targetRgb":[90,90,90]},{"id":"memory-c","muralId":"memory","name":"Final Panel","icon":"fas fa-image","x":8,"y":1,"sourceRgb":[15,135,210],"targetRgb":[120,120,120]}]}}},{"chapter":2,"level_name":"The Palette Lock","description":"Combine color transformations to open the prism vault.","objective":"Open three locks using the right transformation: <span class=\"highlight\">+40 brightness</span>, <span class=\"highlight\">inversion</span>, then <span class=\"highlight\">grayscale</span>.","starter_code":"# Restore the three locks in order.\nbright_r, bright_g, bright_b = 110, 60, 30\ninverse_r, inverse_g, inverse_b = 20, 100, 160\ngray_r, gray_g, gray_b = 20, 80, 140\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"2-5","stage_type":"challenge","xp_reward":200,"arena":{"theme":"archive","blockMovement":true,"cols":10,"rows":6,"spawn":{"x":1,"y":3},"colorTargets":[{"id":"bright-lock","name":"Radiance Lock","icon":"fas fa-lock","x":2,"y":1,"sourceRgb":[110,60,30],"targetRgb":[150,100,70]},{"id":"inverse-lock","name":"Mirror Lock","icon":"fas fa-lock","x":5,"y":1,"sourceRgb":[20,100,160],"targetRgb":[235,155,95]},{"id":"gray-lock","name":"Silver Lock","icon":"fas fa-lock","x":8,"y":1,"sourceRgb":[20,80,140],"targetRgb":[80,80,80]}],"obstacles":[{"x":3,"y":3},{"x":6,"y":3}]}}},{"chapter":2,"level_name":"The Living Atlas","description":"Restore three Atlas pages and open the final gate.","objective":"Restore the Atlas pages with <span class=\"highlight\">+50 brightness</span>, <span class=\"highlight\">inversion</span>, and <span class=\"highlight\">grayscale</span>. Then move beside the Atlas Gate.","starter_code":"# Restore all three pages, then reach the gate at (9, 4).\nlight_r, light_g, light_b = 40, 60, 90\nmirror_r, mirror_g, mirror_b = 20, 100, 180\nsilver_r, silver_g, silver_b = 120, 60, 30\n\n","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"2-6","stage_type":"boss","xp_reward":500,"arena":{"theme":"archive","blockMovement":true,"cols":10,"rows":6,"spawn":{"x":1,"y":4},"murals":[{"id":"atlas","name":"Living Atlas"}],"colorTargets":[{"id":"atlas-light","muralId":"atlas","name":"Sunlit Page","icon":"fas fa-scroll","x":2,"y":1,"sourceRgb":[40,60,90],"targetRgb":[90,110,140]},{"id":"atlas-mirror","muralId":"atlas","name":"Mirror Page","icon":"fas fa-scroll","x":5,"y":1,"sourceRgb":[20,100,180],"targetRgb":[235,155,75]},{"id":"atlas-gray","muralId":"atlas","name":"Silver Page","icon":"fas fa-scroll","x":8,"y":1,"sourceRgb":[120,60,30],"targetRgb":[70,70,70]}],"gate":{"x":9,"y":4,"name":"Atlas Gate"},"obstacles":[{"x":4,"y":4},{"x":7,"y":4}]}}},{"chapter":3,"level_name":"The Inscription Wall","description":"Learn about lists and how to create them.","objective":"Return a new list containing the three pixels in their original order. <span class=\"highlight\">A digital image is a list of RGB pixels; each rune is one pixel.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[220,40,35],[40,200,90],[35,90,220]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-1","stage_type":"lesson","xp_reward":220,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-1-image","name":"The Inscription Wall image"}],"colorTargets":[{"id":"3-1-pixel-0","name":"Pixel 1","icon":"fas fa-th-list","x":2,"y":2,"sourceRgb":[220,40,35],"targetRgb":[220,40,35],"muralId":"3-1-image"},{"id":"3-1-pixel-1","name":"Pixel 2","icon":"fas fa-th-list","x":5,"y":2,"sourceRgb":[40,200,90],"targetRgb":[40,200,90],"muralId":"3-1-image"},{"id":"3-1-pixel-2","name":"Pixel 3","icon":"fas fa-th-list","x":8,"y":2,"sourceRgb":[35,90,220],"targetRgb":[35,90,220],"muralId":"3-1-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":3,"level_name":"Rune Positions","description":"Use pixel positions to repair a scrambled image.","objective":"The first and last pixels were swapped. Return them in the correct order. <span class=\"highlight\">Pixel indexing locates an exact position in an image row.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[35,90,220],[40,200,90],[220,40,35]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-2","stage_type":"challenge","xp_reward":240,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-2-image","name":"Rune Positions image"}],"colorTargets":[{"id":"3-2-pixel-0","name":"Pixel 1","icon":"fas fa-hand-pointer","x":2,"y":2,"sourceRgb":[35,90,220],"targetRgb":[220,40,35],"muralId":"3-2-image"},{"id":"3-2-pixel-1","name":"Pixel 2","icon":"fas fa-hand-pointer","x":5,"y":2,"sourceRgb":[40,200,90],"targetRgb":[40,200,90],"muralId":"3-2-image"},{"id":"3-2-pixel-2","name":"Pixel 3","icon":"fas fa-hand-pointer","x":8,"y":2,"sourceRgb":[220,40,35],"targetRgb":[35,90,220],"muralId":"3-2-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":3,"level_name":"The Matrix Search","description":"Find values in lists using .index().","objective":"Find the pixel with the most red using .index() and max(). Turn that pixel gold. <span class=\"highlight\">Searching a pixel row finds the brightest red sample, a simple feature detector.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[20,50,90],[180,30,50],[70,70,70]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-3","stage_type":"challenge","xp_reward":280,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-3-image","name":"The Matrix Search image"}],"colorTargets":[{"id":"3-3-pixel-0","name":"Pixel 1","icon":"fas fa-search","x":2,"y":2,"sourceRgb":[20,50,90],"targetRgb":[20,50,90],"muralId":"3-3-image"},{"id":"3-3-pixel-1","name":"Pixel 2","icon":"fas fa-search","x":5,"y":2,"sourceRgb":[180,30,50],"targetRgb":[255,200,40],"muralId":"3-3-image"},{"id":"3-3-pixel-2","name":"Pixel 3","icon":"fas fa-search","x":8,"y":2,"sourceRgb":[70,70,70],"targetRgb":[70,70,70],"muralId":"3-3-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":3,"level_name":"The Echo Loop","description":"Learn for loops to iterate over lists.","objective":"Brighten every channel by 30, stopping at 255. <span class=\"highlight\">A for loop applies the same image filter to every pixel.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[50,70,90],[140,40,70],[240,220,200]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-4","stage_type":"lesson","xp_reward":290,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-4-image","name":"The Echo Loop image"}],"colorTargets":[{"id":"3-4-pixel-0","name":"Pixel 1","icon":"fas fa-sync-alt","x":2,"y":2,"sourceRgb":[50,70,90],"targetRgb":[80,100,120],"muralId":"3-4-image"},{"id":"3-4-pixel-1","name":"Pixel 2","icon":"fas fa-sync-alt","x":5,"y":2,"sourceRgb":[140,40,70],"targetRgb":[170,70,100],"muralId":"3-4-image"},{"id":"3-4-pixel-2","name":"Pixel 3","icon":"fas fa-sync-alt","x":8,"y":2,"sourceRgb":[240,220,200],"targetRgb":[255,250,230],"muralId":"3-4-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":3,"level_name":"Broken Arrays","description":"Repair a broken pixel processing loop.","objective":"Fix the loop so it adds 20 to red only, capped at 255; keep green and blue. <span class=\"highlight\">A faulty loop shifts pixel channels and corrupts an image.</span>","starter_code":"def transform(pixels):\n    result = []\n    for pixel in pixels:\n        result.append([min(255, pixel[1] + 20), pixel[0], pixel[2]])\n    return result\n\npixels = [[20,40,90],[80,140,30],[250,20,50]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-5","stage_type":"challenge","xp_reward":310,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-5-image","name":"Broken Arrays image"}],"colorTargets":[{"id":"3-5-pixel-0","name":"Pixel 1","icon":"fas fa-bug","x":2,"y":2,"sourceRgb":[20,40,90],"targetRgb":[40,40,90],"muralId":"3-5-image"},{"id":"3-5-pixel-1","name":"Pixel 2","icon":"fas fa-bug","x":5,"y":2,"sourceRgb":[80,140,30],"targetRgb":[100,140,30],"muralId":"3-5-image"},{"id":"3-5-pixel-2","name":"Pixel 3","icon":"fas fa-bug","x":8,"y":2,"sourceRgb":[250,20,50],"targetRgb":[255,20,50],"muralId":"3-5-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":3,"level_name":"Pixel Trail","description":"Walk through a row of pixels and restore each color.","objective":"Reverse the row with a loop and append(), so the rune trail reads from right to left. <span class=\"highlight\">Traversing a pixel row restores an image one sample at a time.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[35,90,220],[40,200,90],[220,40,35]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-7","stage_type":"challenge","xp_reward":330,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-7-image","name":"Pixel Trail image"}],"colorTargets":[{"id":"3-7-pixel-0","name":"Pixel 1","icon":"fas fa-route","x":2,"y":2,"sourceRgb":[35,90,220],"targetRgb":[220,40,35],"muralId":"3-7-image"},{"id":"3-7-pixel-1","name":"Pixel 2","icon":"fas fa-route","x":5,"y":2,"sourceRgb":[40,200,90],"targetRgb":[40,200,90],"muralId":"3-7-image"},{"id":"3-7-pixel-2","name":"Pixel 3","icon":"fas fa-route","x":8,"y":2,"sourceRgb":[220,40,35],"targetRgb":[35,90,220],"muralId":"3-7-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":3,"level_name":"The Hidden Pattern","description":"Find a repeated color pattern in the rune image.","objective":"If the outer pixels match, make the center gold; otherwise leave the row unchanged. <span class=\"highlight\">A repeated pixel pattern can reveal a feature hidden in an image.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[220,40,35],[30,30,30],[220,40,35]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-8","stage_type":"challenge","xp_reward":350,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-8-image","name":"The Hidden Pattern image"}],"colorTargets":[{"id":"3-8-pixel-0","name":"Pixel 1","icon":"fas fa-chess-board","x":2,"y":2,"sourceRgb":[220,40,35],"targetRgb":[220,40,35],"muralId":"3-8-image"},{"id":"3-8-pixel-1","name":"Pixel 2","icon":"fas fa-chess-board","x":5,"y":2,"sourceRgb":[30,30,30],"targetRgb":[255,200,40],"muralId":"3-8-image"},{"id":"3-8-pixel-2","name":"Pixel 3","icon":"fas fa-chess-board","x":8,"y":2,"sourceRgb":[220,40,35],"targetRgb":[220,40,35],"muralId":"3-8-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":3,"level_name":"The Peak Trial","description":"Use lists, indexing, and loops to restore the summit image.","objective":"Brighten every pixel by 20, then mark the brightest original red pixel gold. <span class=\"highlight\">Indexing, searching, and loops combine to locate and restore image features.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[30,40,50],[200,30,20],[70,80,90]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)\nhero.move_down(2)","difficulty":"Hard","map_data":{"catalog":"spectrum_stages_v1","stage_key":"3-6","stage_type":"boss","xp_reward":450,"arena":{"theme":"peaks","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"3-6-image","name":"The Peak Trial image"}],"colorTargets":[{"id":"3-6-pixel-0","name":"Pixel 1","icon":"fas fa-crown","x":2,"y":2,"sourceRgb":[30,40,50],"targetRgb":[50,60,70],"muralId":"3-6-image"},{"id":"3-6-pixel-1","name":"Pixel 2","icon":"fas fa-crown","x":5,"y":2,"sourceRgb":[200,30,20],"targetRgb":[255,200,40],"muralId":"3-6-image"},{"id":"3-6-pixel-2","name":"Pixel 3","icon":"fas fa-crown","x":8,"y":2,"sourceRgb":[70,80,90],"targetRgb":[90,100,110],"muralId":"3-6-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}],"gate":{"x":9,"y":4,"name":"Summit Gate"}}}},{"chapter":4,"level_name":"The Crossroads","description":"Learn if/elif/else conditional logic.","objective":"For every pixel, average its RGB values. Use white when the average is at least 128, otherwise black. <span class=\"highlight\">Thresholding turns image brightness into a black or white mask.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[30,30,30],[180,180,180],[90,150,120]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-1","stage_type":"lesson","xp_reward":300,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-1-image","name":"The Crossroads image"}],"colorTargets":[{"id":"4-1-pixel-0","name":"Pixel 1","icon":"fas fa-code-branch","x":2,"y":2,"sourceRgb":[30,30,30],"targetRgb":[0,0,0],"muralId":"4-1-image"},{"id":"4-1-pixel-1","name":"Pixel 2","icon":"fas fa-code-branch","x":5,"y":2,"sourceRgb":[180,180,180],"targetRgb":[255,255,255],"muralId":"4-1-image"},{"id":"4-1-pixel-2","name":"Pixel 3","icon":"fas fa-code-branch","x":8,"y":2,"sourceRgb":[90,150,120],"targetRgb":[0,0,0],"muralId":"4-1-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":4,"level_name":"Path Selection","description":"Choose an image filter with if, elif, and else.","objective":"Classify average brightness: below 85 blue, below 170 gold, otherwise white. <span class=\"highlight\">if/elif/else selects a different filter for each brightness range.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[30,30,30],[120,120,120],[220,220,220]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-2","stage_type":"challenge","xp_reward":320,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-2-image","name":"Path Selection image"}],"colorTargets":[{"id":"4-2-pixel-0","name":"Pixel 1","icon":"fas fa-directions","x":2,"y":2,"sourceRgb":[30,30,30],"targetRgb":[35,90,220],"muralId":"4-2-image"},{"id":"4-2-pixel-1","name":"Pixel 2","icon":"fas fa-directions","x":5,"y":2,"sourceRgb":[120,120,120],"targetRgb":[255,200,40],"muralId":"4-2-image"},{"id":"4-2-pixel-2","name":"Pixel 3","icon":"fas fa-directions","x":8,"y":2,"sourceRgb":[220,220,220],"targetRgb":[240,240,240],"muralId":"4-2-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":4,"level_name":"Truth and Lies","description":"Combine boolean masks to reveal hidden pixels.","objective":"Keep a pixel only if red is above 100 AND blue is below 100; make all others black. <span class=\"highlight\">Boolean masks select pixels by combining channel conditions.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[180,30,40],[40,200,40],[180,30,180]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-3","stage_type":"challenge","xp_reward":340,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-3-image","name":"Truth and Lies image"}],"colorTargets":[{"id":"4-3-pixel-0","name":"Pixel 1","icon":"fas fa-toggle-on","x":2,"y":2,"sourceRgb":[180,30,40],"targetRgb":[180,30,40],"muralId":"4-3-image"},{"id":"4-3-pixel-1","name":"Pixel 2","icon":"fas fa-toggle-on","x":5,"y":2,"sourceRgb":[40,200,40],"targetRgb":[0,0,0],"muralId":"4-3-image"},{"id":"4-3-pixel-2","name":"Pixel 3","icon":"fas fa-toggle-on","x":8,"y":2,"sourceRgb":[180,30,180],"targetRgb":[0,0,0],"muralId":"4-3-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":4,"level_name":"Broken Bridges","description":"Repair conditional logic in a broken image mask.","objective":"Fix the comparison: keep pixels whose average brightness is at least 100; black out the rest. <span class=\"highlight\">A reversed comparison breaks a threshold mask and hides the wrong pixels.</span>","starter_code":"def transform(pixels):\n    result = []\n    for pixel in pixels:\n        if sum(pixel) / 3 < 100:\n            result.append(pixel)\n        else:\n            result.append([0, 0, 0])\n    return result\n\npixels = [[30,30,30],[100,100,100],[200,150,100]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-4","stage_type":"challenge","xp_reward":360,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-4-image","name":"Broken Bridges image"}],"colorTargets":[{"id":"4-4-pixel-0","name":"Pixel 1","icon":"fas fa-bug","x":2,"y":2,"sourceRgb":[30,30,30],"targetRgb":[0,0,0],"muralId":"4-4-image"},{"id":"4-4-pixel-1","name":"Pixel 2","icon":"fas fa-bug","x":5,"y":2,"sourceRgb":[100,100,100],"targetRgb":[100,100,100],"muralId":"4-4-image"},{"id":"4-4-pixel-2","name":"Pixel 3","icon":"fas fa-bug","x":8,"y":2,"sourceRgb":[200,150,100],"targetRgb":[200,150,100],"muralId":"4-4-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":4,"level_name":"The Color Mixer","description":"Use conditionals to mix colors dynamically.","objective":"If red is strongest, add 40 green; otherwise add 40 blue. Cap the changed channel at 255. <span class=\"highlight\">Conditional color mixing changes RGB channels based on the source pixel.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[190,30,20],[20,180,40],[10,20,210]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-5","stage_type":"challenge","xp_reward":380,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-5-image","name":"The Color Mixer image"}],"colorTargets":[{"id":"4-5-pixel-0","name":"Pixel 1","icon":"fas fa-tint","x":2,"y":2,"sourceRgb":[190,30,20],"targetRgb":[190,70,20],"muralId":"4-5-image"},{"id":"4-5-pixel-1","name":"Pixel 2","icon":"fas fa-tint","x":5,"y":2,"sourceRgb":[20,180,40],"targetRgb":[20,180,80],"muralId":"4-5-image"},{"id":"4-5-pixel-2","name":"Pixel 3","icon":"fas fa-tint","x":8,"y":2,"sourceRgb":[10,20,210],"targetRgb":[10,20,250],"muralId":"4-5-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":4,"level_name":"Shadow Boundaries","description":"Detect light and shadow boundaries between pixels.","objective":"Make a pixel gold if its average brightness differs from the previous pixel by at least 80; keep other pixels. <span class=\"highlight\">Edge detection compares neighboring pixels to find a light to shadow boundary.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[30,30,30],[200,200,200],[210,210,210]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-7","stage_type":"challenge","xp_reward":400,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-7-image","name":"Shadow Boundaries image"}],"colorTargets":[{"id":"4-7-pixel-0","name":"Pixel 1","icon":"fas fa-adjust","x":2,"y":2,"sourceRgb":[30,30,30],"targetRgb":[30,30,30],"muralId":"4-7-image"},{"id":"4-7-pixel-1","name":"Pixel 2","icon":"fas fa-adjust","x":5,"y":2,"sourceRgb":[200,200,200],"targetRgb":[255,200,40],"muralId":"4-7-image"},{"id":"4-7-pixel-2","name":"Pixel 3","icon":"fas fa-adjust","x":8,"y":2,"sourceRgb":[210,210,210],"targetRgb":[210,210,210],"muralId":"4-7-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":4,"level_name":"The Color Seal","description":"Combine masks and color mixing to open the seal.","objective":"Turn pixels with every channel below 100 into gold. For all others, brighten blue by 20. <span class=\"highlight\">A color mask identifies dark pixels before applying an RGB transformation.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[20,30,40],[180,60,40],[40,150,240]]\ncolors = transform(pixels)\nfor color in colors:\n    hero.cast_color(color[0], color[1], color[2])\n    hero.move_right(3)","difficulty":"Medium","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-8","stage_type":"challenge","xp_reward":420,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-8-image","name":"The Color Seal image"}],"colorTargets":[{"id":"4-8-pixel-0","name":"Pixel 1","icon":"fas fa-shield-alt","x":2,"y":2,"sourceRgb":[20,30,40],"targetRgb":[255,200,40],"muralId":"4-8-image"},{"id":"4-8-pixel-1","name":"Pixel 2","icon":"fas fa-shield-alt","x":5,"y":2,"sourceRgb":[180,60,40],"targetRgb":[180,60,60],"muralId":"4-8-image"},{"id":"4-8-pixel-2","name":"Pixel 3","icon":"fas fa-shield-alt","x":8,"y":2,"sourceRgb":[40,150,240],"targetRgb":[40,150,255],"muralId":"4-8-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}]}}},{"chapter":4,"level_name":"The Light Convergence","description":"Restore the final image with a conditional RGB filter.","objective":"If average brightness is below 85, make white. If red is strongest, add 50 blue. Otherwise keep the pixel. Avoid the marked shadow tiles, restore all three seals, and reach the gate. <span class=\"highlight\">Two minutes of active execution time.</span>","starter_code":"def transform(pixels):\n    pass  # Write the pixel filter here\n\npixels = [[20,30,40],[200,40,30],[40,180,90]]\ncolors = transform(pixels)\nfor index, color in enumerate(colors):\n    hero.cast_color(color[0], color[1], color[2])\n    if index < 2:\n        hero.move_up(1)\n        hero.move_right(3)\n        hero.move_down(1)\nhero.move_right(2)\nhero.move_down(2)","difficulty":"Hard","map_data":{"catalog":"spectrum_stages_v1","stage_key":"4-6","stage_type":"boss","xp_reward":600,"arena":{"theme":"cavern","blockMovement":true,"cols":10,"rows":5,"spawn":{"x":1,"y":2},"murals":[{"id":"4-6-image","name":"The Light Convergence image"}],"colorTargets":[{"id":"4-6-pixel-0","name":"Color Seal 1","icon":"fas fa-sun","x":2,"y":2,"sourceRgb":[20,30,40],"targetRgb":[255,255,255],"muralId":"4-6-image"},{"id":"4-6-pixel-1","name":"Color Seal 2","icon":"fas fa-sun","x":5,"y":2,"sourceRgb":[200,40,30],"targetRgb":[200,40,80],"muralId":"4-6-image"},{"id":"4-6-pixel-2","name":"Color Seal 3","icon":"fas fa-sun","x":8,"y":2,"sourceRgb":[40,180,90],"targetRgb":[40,180,90],"muralId":"4-6-image"}],"obstacles":[{"x":3,"y":0},{"x":6,"y":4}],"gate":{"x":9,"y":4,"name":"Spectrum Gate"},"boss":{"name":"Krakk, Summus Magus Monotoniae","x":9,"y":0},"hazards":[{"x":3,"y":2},{"x":6,"y":2}]}}}]'::jsonb) AS x(chapter int, level_name text, description text, objective text, starter_code text, difficulty text, map_data jsonb)
WHERE NOT EXISTS (SELECT 1 FROM public.levels l WHERE l.map_data->>'catalog' = x.map_data->>'catalog' AND l.map_data->>'stage_key' = x.map_data->>'stage_key');
UPDATE public.achievements AS a
SET title = x.title, description = x.description
FROM jsonb_to_recordset('[{"title":"The Awakening","description":"Complete The Awakening Altar.","unlock_condition":"spectrum_stages_v1:stage:1-1"},{"title":"The Prism Path Master","description":"Complete every stage in THE RED FOREST.","unlock_condition":"spectrum_stages_v1:region:1"},{"title":"The Chromatic Archive Master","description":"Complete every stage in THE SCHOLAR''S ARCHIVE.","unlock_condition":"spectrum_stages_v1:region:2"},{"title":"The Matrix Master","description":"Complete every stage in ASH PEAKS.","unlock_condition":"spectrum_stages_v1:region:3"},{"title":"The Light Master","description":"Complete every stage in WHISPERING CAVERNS.","unlock_condition":"spectrum_stages_v1:region:4"},{"title":"Lost Spectrum Restored","description":"Complete all 29 stages of the current adventure.","unlock_condition":"spectrum_stages_v1:all"}]'::jsonb) AS x(title text, description text, unlock_condition text)
WHERE a.unlock_condition = x.unlock_condition;
INSERT INTO public.achievements (title, description, unlock_condition)
SELECT x.title, x.description, x.unlock_condition
FROM jsonb_to_recordset('[{"title":"The Awakening","description":"Complete The Awakening Altar.","unlock_condition":"spectrum_stages_v1:stage:1-1"},{"title":"The Prism Path Master","description":"Complete every stage in THE RED FOREST.","unlock_condition":"spectrum_stages_v1:region:1"},{"title":"The Chromatic Archive Master","description":"Complete every stage in THE SCHOLAR''S ARCHIVE.","unlock_condition":"spectrum_stages_v1:region:2"},{"title":"The Matrix Master","description":"Complete every stage in ASH PEAKS.","unlock_condition":"spectrum_stages_v1:region:3"},{"title":"The Light Master","description":"Complete every stage in WHISPERING CAVERNS.","unlock_condition":"spectrum_stages_v1:region:4"},{"title":"Lost Spectrum Restored","description":"Complete all 29 stages of the current adventure.","unlock_condition":"spectrum_stages_v1:all"}]'::jsonb) AS x(title text, description text, unlock_condition text)
WHERE NOT EXISTS (SELECT 1 FROM public.achievements a WHERE a.unlock_condition = x.unlock_condition);
COMMIT;
